✍️ How to Generate NAMESPACE
In .R files:
#' @export
r_func &lt;- function(x) { ... }

In .cpp files:
// [[Rcpp::export]]
double myRcpp-func(int x, double y) { ... }

Pure R Code

hankelize_R &lt;- function(X){
  L &lt;- nrow(X)
  K &lt;- ncol(X)
  N &lt;- L + K - 1
  result &lt;- numeric(N)
  count &lt;- numeric(N)

  for(i in 1:L){
    for(j in 1:K){
      result[i + j - 1] &lt;- result[i + j - 1] + X[i,j]
      count[i + j - 1] &lt;- count[i + j - 1] + 1
    }
  }

  return(result / count)
}

Rcpp Code

library(Rcpp)

cppFunction('
NumericVector hankelize_rcpp(NumericMatrix X) {
  int L = X.nrow();
  int K = X.ncol();
  int N = L + K - 1;

  NumericVector result(N);
  NumericVector count(N);

  for(int i = 0; i &lt; L; i++){
    for(int j = 0; j &lt; K; j++){
      result[i + j] += X(i,j);
      count[i + j] += 1;
    }
  }

  for(int i = 0; i &lt; N; i++){
    result[i] /= count[i];
  }

  return result;
}')

