5. Add Supporting Files - src/


Add .cpp files in the src/ folder

Compiled code is linked to R through Rcpp

Called from standard R functions in the R/ folder



Create a new file: src/knn_pred.cpp
// [[Rcpp::depends(Rcpp)]]
#include &lt;Rcpp.h&gt;
using namespace Rcpp;

// [[Rcpp::export]]
List knn_pred_cpp(NumericMatrix train_x,
                           NumericVector train_y,
                           NumericMatrix test_x,
                           int k) {
  int n = train_x.nrow(), 
    p = train_x.ncol(), 
    m = test_x.nrow();
  NumericVector preds(m);
  int id_length = m * k;
  IntegerVector ids(id_length);


  for (int j = 0; j &lt; m; ++j) {
    // compute and store (distance,index)
    std::vector&lt;std::pair&lt;double,int&gt;&gt; dists(n);
    for (int i = 0; i &lt; n; ++i) {
      double sumsq = 0;
      for (int d = 0; d &lt; p; ++d) {
        double diff = train_x(i,d) - test_x(j,d);
        sumsq += diff * diff;
      }
      dists[i] = std::make_pair(sumsq, i);
    }
    // partial sort to get k nearest
    std::nth_element(dists.begin(), dists.begin() + k, dists.end(),
                     [](auto &a, auto &b){ return a.first &lt; b.first; });
    double s = 0;
    for (int r = 0; r &lt; k; ++r) {
      s += train_y[dists[r].second];
      ids[j * k  + r] = std::get&lt;1&gt;(dists[r]);
    }
    preds[j] = s / k;
  }

  List ret;
  ret["preds"] = preds;
  ret["ids"] = ids + 1;

  return ret;
}

