// [[Rcpp::export]]
int rec_fib_cpp(int n) {
  if (n &lt; 2) return(n);
  return(rec_fib_cpp(n - 1) + rec_fib_cpp(n - 2)); 
}

// [[Rcpp::export]]
long long fib_cpp(int n) {
  if (n &lt;= 1) return n;
  long long a = 0, b = 1, temp;
  for (int i = 2; i &lt;= n; ++i) {
    temp = b;
    b = a + b;
    a = temp;
  }
  return b;
}

